-- After the seed with the column statistics revokes, as the instance owner: a table of the types the value-free column read has to spell, one the agent user may read and one it may not, and the catalog's own spelling of each for comparison.
CREATE DISTINCT TYPE APP.LIBREDB_VF_MONEY AS DECIMAL(9, 2) WITH COMPARISONS;
CREATE TABLE APP.LIBREDB_VF_TYPES (ID INTEGER NOT NULL PRIMARY KEY, C_DF16 DECFLOAT(16), C_DF34 DECFLOAT(34), C_VC32 VARCHAR(20 CODEUNITS32), C_G32 GRAPHIC(5 CODEUNITS32), C_VCBIT VARCHAR(8) FOR BIT DATA, C_BIN BINARY(8), C_VBIN VARBINARY(40), C_MONEY APP.LIBREDB_VF_MONEY, C_NUM NUMERIC(7, 3), C_FLOAT FLOAT, C_TEXT VARCHAR(30) DEFAULT 'it''s', C_TS TIMESTAMP(3) DEFAULT CURRENT TIMESTAMP, C_DBCLOB DBCLOB(2K), C_DATE DATE DEFAULT '2024-01-01');
CREATE TABLE APP.LIBREDB_VF_HIDDEN (ID INTEGER NOT NULL, C_DF16 DECFLOAT(16), C_DF34 DECFLOAT(34), CONSTRAINT LIBREDB_VF_HIDDEN_PK PRIMARY KEY (ID));
CREATE VIEW APP.LIBREDB_VF_VIEW AS SELECT ID, C_DF34 FROM APP.LIBREDB_VF_TYPES;
GRANT SELECT ON APP.LIBREDB_VF_TYPES TO USER AGENT_RO;
SELECT VARCHAR(COLNAME, 11) AS COLNAME, VARCHAR(TYPENAME, 18) AS TYPENAME, LENGTH, SCALE, CODEPAGE, VARCHAR(TYPESTRINGUNITS, 11) AS UNITS, STRINGUNITSLENGTH AS SUL, NULLS, KEYSEQ, VARCHAR("DEFAULT", 30) AS DEFAULT FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'APP' AND TABNAME IN ('LIBREDB_VF_TYPES', 'ORDERS') ORDER BY TABNAME, COLNO;
SELECT VARCHAR(TABSCHEMA, 8) AS TABSCHEMA, VARCHAR(TABNAME, 18) AS TABNAME, VARCHAR(COLNAME, 10) AS COLNAME, CODEPAGE FROM SYSCAT.COLUMNS WHERE TABSCHEMA = 'SYSIBM' AND TABNAME = 'SYSDUMMY1';
